            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def excel_to_csv_text(path: str) -> str:
    """Convert the active sheet of an .xlsx file to CSV text, keeping one line per sheet row."""
    from openpyxl import load_workbook
    workbook = load_workbook(path, read_only=True, data_only=True)
    try:
        sheet = workbook.active
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator='\n')
        for cells in sheet.iter_rows(values_only=True):
            writer.writerow(['' if c is None else str(c).replace('\r', ' ').replace('\n', ' ') for c in cells])
        return buffer.getvalue()
    finally:
        workbook.close()


def validate_user_upload(path: str) -> dict[str, Any]:
    """Validate an uploaded users export (.csv or .xlsx) and report every invalid row.

    Returns {'ok', 'valid_count', 'invalid_count', 'invalid_rows': [{'row', 'errors'}]}.
    Row numbers match the spreadsheet row (header is row 1). Validation continues
    past errors so all bad rows are reported at once.
    """
    extension = os.path.splitext(path)[1].lower()
    if extension in ('.xlsx', '.xlsm'):
        text = excel_to_csv_text(path)
    elif extension in ('.csv', '.txt'):
        with open(path, encoding='utf-8-sig', newline='') as handle:
            text = handle.read()
    else:
        return {'ok': False, 'valid_count': 0, 'invalid_count': 1,
                'invalid_rows': [{'row': 1, 'errors': [f'unsupported file type: {extension or "none"}']}]}
    valid, errors = import_users(text)
    return {'ok': not errors, 'valid_count': len(valid), 'invalid_count': len(errors),
            'invalid_rows': sorted(errors, key=lambda e: e['row'])}

